example.snippet:
package main

import (
	"context"

	"dagger/my-module/internal/dagger"
)

type MyModule struct{}

// Build and publish image from existing Dockerfile
func (m *MyModule) Build(
	ctx context.Context,
	// location of directory containing Dockerfile
	src *dagger.Directory,
) (string, error) {
	ref, err := dag.Container().
		WithDirectory("/src", src).
		WithWorkdir("/src").
		Directory("/src").
		DockerBuild(). // build from Dockerfile
		Publish(ctx, "ttl.sh/hello-dagger")

	if err != nil {
		return "", err
	}

	return ref, nil
}

from typing import Annotated
import dagger from dagger import Doc, dag, function, object_type
@object_type class MyModule: @function async def build( self, src: Annotated[ dagger.Directory, Doc("location of directory containing Dockerfile"), ], ) -> str: """Build and publish image from existing Dockerfile""" ref = ( dag.container() .with_directory("/src", src) .with_workdir("/src") .directory("/src") .docker_build() # build from Dockerfile .publish("ttl.sh/hello-dagger") ) return await ref

import { dag, Directory, object, func } from "@dagger.io/dagger"

@object()
class MyModule {
  /**
   * Build and publish image from existing Dockerfile
   * @param src location of directory containing Dockerfile
   */
  @func()
  async build(src: Directory): Promise {
    const ref = await dag
      .container()
      .withDirectory("/src", src)
      .withWorkdir("/src")
      .directory("/src")
      .dockerBuild() // build from Dockerfile
      .publish("ttl.sh/hello-dagger")

    return ref
  }
}
